11 | import BaseProvider from './base-provider.js';
12 | 
13 | class OpenAIProvider extends BaseProvider {
14 |     constructor(config) {
15 |         super(config);
16 |         this.name = config.name || 'OpenAI';
17 |         this.apiKey = config.apiKey;
