import { Terminal, Pause, Play } from 'lucide-react';

interface LogEntry {
  id: string;
  timestamp: string;
  level: 'info' | 'warn' | 'error' | 'debug';
  message: string;
}

interface LiveLogProps {
  logs: LogEntry[];
  agentId: string;
  isRunning?: boolean;
}

const LiveLog: React.FC<LiveLogProps> = ({ logs, agentId, isRunning = true }) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    if (!paused && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs, paused]);

  const getLevelColor = (level: LogEntry['level']) => {
    switch (level) {
      case 'error': return 'text-red-400';
      case 'warn': return 'text-yellow-400';
      case 'debug': return 'text-blue-400';
      default: return 'text-cyan-300';
    }
  };

  return (
    <div className="flex flex-col h-full bg-black/80 border border-cyan-900/50 rounded-lg overflow-hidden shadow-[0_0_15px_rgba(0,255,255,0.1)] backdrop-blur-sm">
      <div className="flex items-center justify-between px-4 py-2 border-b border-cyan-900/50 bg-cyan-950/30">
        <div className="flex items-center gap-2 text-cyan-400">
          <Terminal size={16} />
          <span className="text-xs font-mono tracking-wider uppercase">Live Terminal // {agentId}</span>
        </div>
        <button
          onClick={() => setPaused(!paused)}
          className="flex items-center gap-1 px-2 py-1 text-xs font-mono text-cyan-300 hover:text-cyan-100 hover:bg-cyan-900/40 rounded transition-colors"
        >
          {paused ? <Play size={12} /> : <Pause size={12} />}
          {paused ? 'RESUME' : 'PAUSE'}
        </button>
      </div>

      <div
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-3 font-mono text-xs leading-relaxed scrollbar-thin scrollbar-thumb-cyan-900 scrollbar-track-transparent"
      >
        {logs.length === 0 ? (
          <div className="text-gray-500 italic">Waiting for agent logs...</div>
        ) : (
          logs.map((log) => (
            <div key={log.id} className="flex gap-2 hover:bg-cyan-900/20 px-1 rounded">
              <span className="text-gray-500 shrink-0">[{log.timestamp}]</span>
              <span className={`shrink-0 font-semibold uppercase ${getLevelColor(log.level)}`}>
                {log.level}
              </span>
              <span className="text-gray-300 break-all">{log.message}</span>
            </div>
          ))
        )}
      </div>

      <div className="px-4 py-1 bg-cyan-950/20 border-t border-cyan-900/50 flex justify-between items-center text-[10px] font-mono text-cyan-600">
        <span>STATUS: {isRunning ? 'STREAMING' : 'OFFLINE'}</span>
        <span>ENTRIES: {logs.length}</span>
      </div>
    </div>
  );
};

export default LiveLog;"}

