{"file_path":"C:/Users/Xon/Desktop/multi-agent-dashboard/src/store/agentStore.ts","content":"import { createContext, useContext, useReducer, ReactNode, Dispatch } from 'react';
import { Agent, LogEntry } from '../data/mockData';

type State = {
  agents: Agent[];
  logs: LogEntry[];
  selectedAgentId: string | null;
};

type Action =
  | { type: 'SELECT_AGENT'; payload: string }
  | { type: 'UPDATE_AGENT_STATUS'; payload: { id: string; status: Agent['status'] } }
  | { type: 'ADD_LOG'; payload: LogEntry }
  | { type: 'RESET' };

const initialState: State = {
  agents: [],
  logs: [],
  selectedAgentId: null,
};

function agentReducer(state: State, action: Action): State {
  switch (action.type) {
    case 'SELECT_AGENT':
      return { ...state, selectedAgentId: action.payload };
    case 'UPDATE_AGENT_STATUS':
      return {
        ...state,
        agents: state.agents.map(a =>
          a.id === action.payload.id ? { ...a, status: action.payload.status } : a
        ),
      };
    case 'ADD_LOG':
      return { ...state, logs: [action.payload, ...state.logs].slice(0, 50) };
    case 'RESET':
      return initialState;
    default:
      return state;
  }
}

const AgentContext = createContext<{
  state: State;
  dispatch: Dispatch<Action>;
} | null>(null);

export function AgentProvider({ children, initialData }: { children: ReactNode; initialData: { agents: Agent[]; logs: LogEntry[] } }) {
  const [state, dispatch] = useReducer(agentReducer, { ...initialState, agents: initialData.agents, logs: initialData.logs });
  return <AgentContext.Provider value={{ state, dispatch }}>{children}</AgentContext.Provider>;
}

export function useAgentStore() {
  const context = useContext(AgentContext);
  if (!context) throw new Error('useAgentStore must be used within AgentProvider');
  return context;
}"}

