// Types
export interface Agent {
  id: string;
  name: string;
  status: 'idle' | 'working' | 'error';
  resources: { cpu: number; memory: number };
  lastActivity: string;
}

export interface LogEntry {
  id: string;
  agentId: string;
  message: string;
  timestamp: string;
  level: 'info' | 'warn' | 'error';
}

export interface AppState {
  agents: Agent[];
  logs: LogEntry[];
  selectedAgentId: string | null;
  selectedTask: string | null;
}

type AppAction =
  | { type: 'SET_AGENTS'; payload: Agent[] }
  | { type: 'ADD_LOG'; payload: LogEntry }
  | { type: 'SELECT_AGENT'; payload: string | null }
  | { type: 'SELECT_TASK'; payload: string | null }
  | { type: 'UPDATE_AGENT_STATUS'; payload: { id: string; status: Agent['status'] } };

// Initial State
const initialState: AppState = {
  agents: [
    { id: 'agent-1', name: 'Alpha-01', status: 'idle', resources: { cpu: 12, memory: 34 }, lastActivity: '2 min ago' },
    { id: 'agent-2', name: 'Beta-02', status: 'working', resources: { cpu: 78, memory: 56 }, lastActivity: 'Just now' },
    { id: 'agent-3', name: 'Gamma-03', status: 'error', resources: { cpu: 5, memory: 12 }, lastActivity: '5 min ago' },
  ],
  logs: [
    { id: 'log-1', agentId: 'agent-2', message: 'Starting data processing task...', timestamp: new Date().toISOString(), level: 'info' },
    { id: 'log-2', agentId: 'agent-2', message: 'Loaded 1,247 records from source', timestamp: new Date().toISOString(), level: 'info' },
  ],
  selectedAgentId: 'agent-1',
  selectedTask: null,
};

// Reducer
function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'SET_AGENTS':
      return { ...state, agents: action.payload };
    case 'ADD_LOG':
      return { ...state, logs: [action.payload, ...state.logs].slice(0, 100) };
    case 'SELECT_AGENT':
      return { ...state, selectedAgentId: action.payload };
    case 'SELECT_TASK':
      return { ...state, selectedTask: action.payload };
    case 'UPDATE_AGENT_STATUS':
      return {
        ...state,
        agents: state.agents.map(agent =>
          agent.id === action.payload.id ? { ...agent, status: action.payload.status } : agent
        ),
      };
    default:
      return state;
  }
}

// Context
const AppContext = createContext<{ state: AppState; dispatch: React.Dispatch<AppAction> } | undefined>(undefined);

export function AppProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(appReducer, initialState);
  return <AppContext.Provider value={{ state, dispatch }}>{children}</AppContext.Provider>;
}

export function useAppContext() {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider');
  }
  return context;
}
